impl RuntimeProcess {
    pub fn start(cwd: &Path, initial_module_cid: &str) -> (Self, JsonValue) {
        Self::start_with_args(
            cwd,
            &[
                "program",
                "module",
                "runtime",
                initial_module_cid,
                "--slot",
                "fixture.echo",
                "--authorization",
                AUTHORITY,
                "--format",
                "json",
            ],
        )
    }

    #[allow(dead_code)]
    pub fn resume(cwd: &Path, record_cid: &str, slot: &str) -> (Self, JsonValue) {
        Self::start_with_args(
            cwd,
            &[
                "program",
                "module",
                "runtime",
                "--resume-record",
                record_cid,
                "--slot",
                slot,
                "--authorization",
                AUTHORITY,
                "--format",
                "json",
            ],
        )
    }

    pub fn start_with_args(cwd: &Path, args: &[&str]) -> (Self, JsonValue) {
        Self::start_with_args_and_env(cwd, args, &[])
    }

    pub fn pid(&self) -> u32 {
        self.child.id()
    }

    pub fn request(&mut self, request: JsonValue) -> JsonValue {
        self.send_request(request);
        self.read_response()
    }

    pub fn read_response(&mut self) -> JsonValue {
