        let mut child = command
            .spawn()
            .expect("failed to start program module runtime");
        let input = child.stdin.take().unwrap();
        let output = BufReader::new(child.stdout.take().unwrap());
        let mut runtime = Self {
            child,
            input: Some(input),
            output,
            waited: false,
        };
        let started = runtime.read_response();
        (runtime, started)
    }

    pub fn send_request(&mut self, request: JsonValue) {
        let input = self.input.as_mut().expect("runtime stdin is open");
        writeln!(input, "{}", serde_json::to_string(&request).unwrap()).unwrap();
        input.flush().unwrap();
    }

    pub fn close_input_and_wait(&mut self) -> std::process::ExitStatus {
        drop(self.input.take());
        let status = self.child.wait().unwrap();
        self.waited = true;
        status
    }

    pub fn wait_for_marker(&mut self, marker: &Path, expected: &[u8]) {
        for _ in 0..400 {
            if marker.exists() {
                assert_eq!(std::fs::read(marker).unwrap(), expected);
                return;
            }
            if let Some(status) = self.child.try_wait().unwrap() {
                self.waited = true;
                panic!("runtime exited before pause marker: {status}");
            }
            thread::sleep(Duration::from_millis(25));
        }
        self.kill_and_wait();
        panic!("runtime did not reach the expected pause marker");
    }

    pub fn kill_and_wait(&mut self) {
        drop(self.input.take());
        self.child.kill().unwrap();
        let status = self.child.wait().unwrap();
        self.waited = true;
        assert!(!status.success(), "killed runtime unexpectedly succeeded");
    }
}

